                    obs_for_header["feedback"] = feedback
            except Exception:
                pass
        obs = obs_for_header
        try:
            hrec = header.update(obs_for_header)
            if isinstance(hrec, dict):
                out.update(hrec)
            # debug counter (off by default): track header updates per env step
            try:
