    PRIMITIVE_DEPS = ("P1_BendMetric", "identity memory", "P12_ClosureQuotient (optional)")
    COMBINATOR_FORM = "SC_GatedThreshold"
    FORMULA_STATUS = "provisional"

    mem_len: int = 64
    trace_len: int = 0

